import React, { useEffect, useRef, useState } from 'react';

const TAU = Math.PI * 2;
const clamp = (n: number, min: number, max: number) => Math.max(min, Math.min(max, n));
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const angleDiff = (from: number, to: number) => Math.atan2(Math.sin(to - from), Math.cos(to - from));

interface Point { x: number; y: number; }
interface Food extends Point { hue: number; }

type Phase = 'ready' | 'playing' | 'paused' | 'over';

export default function DynamicSnake() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const frameRef = useRef<number | null>(null);
  const keysRef = useRef<Record<string, boolean>>({});
  const mouseRef = useRef({ x: 0, y: 0, active: false });
  const gameRef = useRef<any>(null);
  const [phase, setPhase] = useState<Phase>('ready');
  const [score, setScore] = useState(0);
  const [best, setBest] = useState(() => {
    try { return Number(localStorage.getItem('dynamic-snake-best') || 0); } catch { return 0; }
  });
  const [length, setLength] = useState(12);

  const newFood = (w: number, h: number, snake: Point[]): Food => {
    for (let i = 0; i < 80; i++) {
      const food = { x: 42 + Math.random() * (w - 84), y: 42 + Math.random() * (h - 84), hue: Math.random() * 360 };
      if (snake.every(p => Math.hypot(p.x - food.x, p.y - food.y) > 42)) return food;
    }
    return { x: w / 2, y: h / 2, hue: Math.random() * 360 };
  };

  const resetGame = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const w = rect.width || 900;
    const h = rect.height || 600;
    const start = { x: w * 0.5, y: h * 0.55 };
    const trail: Point[] = [];
    for (let i = 0; i < 180; i++) trail.push({ x: start.x - i * 4.8, y: start.y });
    gameRef.current = {
      w, h,
      head: { ...start },
      heading: -0.08,
      trail,
      desiredLength: 12,
      speed: 145,
      food: newFood(w, h, trail),
      score: 0,
      last: performance.now(),
      pulse: 0,
    };
    mouseRef.current = { x: start.x + 160, y: start.y - 40, active: false };
    setScore(0);
    setLength(12);
    setPhase('ready');
  };

  const startGame = () => {
    if (!gameRef.current) resetGame();
    if (gameRef.current) gameRef.current.last = performance.now();
    setPhase('playing');
  };

  useEffect(() => {
    resetGame();
    const onKeyDown = (e: KeyboardEvent) => {
      const key = e.key.toLowerCase();
      if (['w', 'a', 's', 'd', 'p', ' '].includes(key)) e.preventDefault();
      keysRef.current[key] = true;
      if (key === 'p') setPhase(p => p === 'playing' ? 'paused' : p === 'paused' ? 'playing' : p);
      if (key === ' ' && (phase === 'ready' || phase === 'over')) startGame();
    };
    const onKeyUp = (e: KeyboardEvent) => { keysRef.current[e.key.toLowerCase()] = false; };
    window.addEventListener('keydown', onKeyDown, { passive: false });
    window.addEventListener('keyup', onKeyUp);
    return () => { window.removeEventListener('keydown', onKeyDown); window.removeEventListener('keyup', onKeyUp); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    let resizeObserver: ResizeObserver | undefined;

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.floor(rect.width * dpr));
      canvas.height = Math.max(1, Math.floor(rect.height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const g = gameRef.current;
      if (g) { g.w = rect.width; g.h = rect.height; }
    };
    resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(canvas);
    resize();

    const draw = (now: number) => {
      const g = gameRef.current;
      const rect = canvas.getBoundingClientRect();
      const w = rect.width, h = rect.height;
      if (!g) { frameRef.current = requestAnimationFrame(draw); return; }
      const dt = Math.min((now - g.last) / 1000, 0.035);
      g.last = now;
      g.w = w; g.h = h;

      if (phase === 'playing') {
        const keys = keysRef.current;
        const steer = (keys.d ? 1 : 0) - (keys.a ? 1 : 0);
        const throttle = (keys.w ? 1 : 0) - (keys.s ? 0.72 : 0);
        const mouse = mouseRef.current;
        let target = g.heading;
        if (mouse.active) target = Math.atan2(mouse.y - g.head.y, mouse.x - g.head.x);
        const turnRate = mouse.active ? 5.2 : 3.8;
        let turn = clamp(angleDiff(g.heading, target), -turnRate * dt, turnRate * dt);
        turn += steer * 4.4 * dt;
        g.heading += turn;
        g.speed = clamp(145 + throttle * 72, 82, 235);
        const nx = g.head.x + Math.cos(g.heading) * g.speed * dt;
        const ny = g.head.y + Math.sin(g.heading) * g.speed * dt;
        g.head = { x: nx, y: ny };
        g.trail.unshift({ ...g.head });

        const spacing = 4.7;
        const maxTrail = Math.ceil((g.desiredLength + 4) * spacing) + 8;
        if (g.trail.length > maxTrail) g.trail.length = maxTrail;
        const hitWall = g.head.x < 12 || g.head.x > w - 12 || g.head.y < 12 || g.head.y > h - 12;
        let hitSelf = false;
        if (g.trail.length > 70) {
          for (let i = 42; i < Math.min(g.trail.length, g.desiredLength * 4.7); i += 4) {
            if (Math.hypot(g.head.x - g.trail[i].x, g.head.y - g.trail[i].y) < 12) { hitSelf = true; break; }
          }
        }
        if (hitWall || hitSelf) {
          setPhase('over');
          const newBest = Math.max(best, g.score);
          setBest(newBest);
          try { localStorage.setItem('dynamic-snake-best', String(newBest)); } catch {}
        }
        if (Math.hypot(g.head.x - g.food.x, g.head.y - g.food.y) < 19) {
          g.desiredLength += 4;
          g.score += 10;
          g.food = newFood(w, h, g.trail);
          setScore(g.score);
          setLength(g.desiredLength);
        }
        g.pulse += dt;
      }

      // Background
      const gradient = ctx.createLinearGradient(0, 0, w, h);
      gradient.addColorStop(0, '#071622');
      gradient.addColorStop(1, '#0d2630');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = 'rgba(121, 220, 202, 0.055)';
      ctx.lineWidth = 1;
      const grid = 36;
      for (let x = 0; x < w; x += grid) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke(); }
      for (let y = 0; y < h; y += grid) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke(); }

      // Border
      ctx.strokeStyle = 'rgba(150, 255, 220, 0.26)';
      ctx.lineWidth = 2;
      ctx.strokeRect(12, 12, w - 24, h - 24);

      // Food glow and fruit
      const f = g.food;
      const pulse = 1 + Math.sin(g.pulse * 4) * 0.08;
      ctx.save();
      ctx.shadowColor = `hsl(${f.hue}, 90%, 65%)`;
      ctx.shadowBlur = 22;
      ctx.fillStyle = `hsl(${f.hue}, 82%, 62%)`;
      ctx.beginPath(); ctx.arc(f.x, f.y, 9 * pulse, 0, TAU); ctx.fill();
      ctx.shadowBlur = 0;
      ctx.fillStyle = 'rgba(255,255,255,.72)';
      ctx.beginPath(); ctx.arc(f.x - 3, f.y - 3, 2.2, 0, TAU); ctx.fill();
      ctx.strokeStyle = '#b9ffcc'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(f.x + 2, f.y - 8); ctx.quadraticCurveTo(f.x + 4, f.y - 15, f.x + 10, f.y - 13); ctx.stroke();
      ctx.restore();

      // Snake body, smoothly sampled from the trail.
      const bodyCount = Math.min(g.desiredLength, Math.floor(g.trail.length / 4.7));
      for (let i = bodyCount - 1; i >= 0; i--) {
        const p = g.trail[Math.min(g.trail.length - 1, Math.floor(i * 4.7))];
        const t = i / Math.max(1, bodyCount - 1);
        const radius = lerp(12.5, 7.2, t);
        const hue = lerp(163, 196, t);
        ctx.fillStyle = `hsl(${hue}, 76%, ${lerp(61, 39, t)}%)`;
        ctx.shadowColor = 'rgba(88, 255, 215, .22)'; ctx.shadowBlur = 9;
        ctx.beginPath(); ctx.arc(p.x, p.y, radius, 0, TAU); ctx.fill();
      }
      ctx.shadowBlur = 0;
      const hx = g.head.x, hy = g.head.y;
      ctx.save();
      ctx.translate(hx, hy); ctx.rotate(g.heading);
      ctx.fillStyle = '#8effd8';
      ctx.beginPath(); ctx.arc(0, 0, 14, 0, TAU); ctx.fill();
      ctx.fillStyle = '#d7fff2';
      ctx.beginPath(); ctx.arc(5, -5, 3.1, 0, TAU); ctx.arc(5, 5, 3.1, 0, TAU); ctx.fill();
      ctx.fillStyle = '#0a3540';
      ctx.beginPath(); ctx.arc(6, -5, 1.5, 0, TAU); ctx.arc(6, 5, 1.5, 0, TAU); ctx.fill();
      ctx.restore();

      // Aim line when the mouse is engaged.
      if (mouseRef.current.active && phase === 'playing') {
        ctx.setLineDash([4, 8]); ctx.strokeStyle = 'rgba(160, 255, 228, .22)'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(g.head.x, g.head.y); ctx.lineTo(mouseRef.current.x, mouseRef.current.y); ctx.stroke(); ctx.setLineDash([]);
        ctx.strokeStyle = 'rgba(160, 255, 228, .45)';
        ctx.beginPath(); ctx.arc(mouseRef.current.x, mouseRef.current.y, 8, 0, TAU); ctx.stroke();
      }

      frameRef.current = requestAnimationFrame(draw);
    };
    frameRef.current = requestAnimationFrame(draw);
    return () => { if (frameRef.current) cancelAnimationFrame(frameRef.current); resizeObserver?.disconnect(); };
  }, [phase, best]);

  const pointFromEvent = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    mouseRef.current = { x: e.clientX - rect.left, y: e.clientY - rect.top, active: true };
  };

  const handlePointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
    pointFromEvent(e);
    if (phase === 'ready' || phase === 'over') startGame();
  };

  const handlePointerLeave = () => { mouseRef.current.active = false; };

  return (
    <main className="min-h-screen bg-[#061017] text-slate-100 flex items-center justify-center p-4 sm:p-8 font-sans">
      <section className="w-full max-w-6xl">
        <header className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 mb-4">
          <div>
            <div className="flex items-center gap-3 mb-1">
              <span className="inline-flex h-3 w-3 rounded-full bg-[#72f5c8] shadow-[0_0_16px_#72f5c8]" />
              <span className="text-xs uppercase tracking-[0.28em] text-[#72f5c8]">Continuous motion</span>
            </div>
            <h1 className="text-3xl sm:text-4xl font-black tracking-tight">Dynamic Snake</h1>
            <p className="text-slate-400 mt-1">No grid. No fixed axes. Guide the snake through open space.</p>
          </div>
          <div className="flex gap-2 text-sm">
            <div className="rounded-xl border border-white/10 bg-white/[.04] px-4 py-2"><span className="text-slate-400">Score</span><strong className="ml-2 text-[#9fffe0]">{score}</strong></div>
            <div className="rounded-xl border border-white/10 bg-white/[.04] px-4 py-2"><span className="text-slate-400">Best</span><strong className="ml-2 text-[#9fffe0]">{best}</strong></div>
            <div className="rounded-xl border border-white/10 bg-white/[.04] px-4 py-2"><span className="text-slate-400">Length</span><strong className="ml-2 text-[#9fffe0]">{length}</strong></div>
          </div>
        </header>

        <div className="relative overflow-hidden rounded-2xl border border-[#72f5c8]/25 shadow-[0_0_60px_rgba(80,220,190,.10)] bg-[#071622]">
          <canvas
            ref={canvasRef}
            className="block w-full h-[min(68vh,620px)] min-h-[420px] touch-none cursor-crosshair"
            onPointerMove={pointFromEvent}
            onPointerDown={handlePointerDown}
            onPointerLeave={handlePointerLeave}
            aria-label="Dynamic snake game canvas"
          />
          {phase !== 'playing' && (
            <div className="absolute inset-0 flex items-center justify-center bg-[#061017]/55 backdrop-blur-[2px]">
              <div className="text-center px-6">
                {phase === 'ready' && <>
                  <div className="text-[#72f5c8] text-xs uppercase tracking-[.3em] mb-3">Ready when you are</div>
                  <h2 className="text-3xl sm:text-5xl font-black mb-3">Aim. Turn. Grow.</h2>
                  <p className="text-slate-300 max-w-md mx-auto mb-6">Move your mouse inside the arena to aim the head, or use A/D to steer and W/S to change speed.</p>
                  <button onClick={startGame} className="rounded-full bg-[#72f5c8] text-[#05232b] px-6 py-3 font-bold hover:bg-[#a2ffe3] transition">Start game <span className="opacity-60">[Space]</span></button>
                </>}
                {phase === 'paused' && <>
                  <div className="text-[#72f5c8] text-xs uppercase tracking-[.3em] mb-3">Game paused</div>
                  <h2 className="text-4xl font-black mb-5">Take a breath</h2>
                  <button onClick={() => setPhase('playing')} className="rounded-full bg-[#72f5c8] text-[#05232b] px-6 py-3 font-bold hover:bg-[#a2ffe3] transition">Resume <span className="opacity-60">[P]</span></button>
                </>}
                {phase === 'over' && <>
                  <div className="text-rose-300 text-xs uppercase tracking-[.3em] mb-3">Run ended</div>
                  <h2 className="text-4xl font-black mb-2">Score {score}</h2>
                  <p className="text-slate-300 mb-6">You reached length {length}. Try a tighter turn.</p>
                  <button onClick={() => { resetGame(); setTimeout(startGame, 0); }} className="rounded-full bg-[#72f5c8] text-[#05232b] px-6 py-3 font-bold hover:bg-[#a2ffe3] transition">Play again <span className="opacity-60">[Space]</span></button>
                </>}
              </div>
            </div>
          )}
          <div className="absolute left-4 top-4 rounded-lg border border-white/10 bg-[#061017]/65 px-3 py-2 text-xs text-slate-300 backdrop-blur-sm">
            <span className="text-[#72f5c8] font-semibold">Mouse aim:</span> continuous heading
          </div>
        </div>

        <footer className="mt-4 flex flex-col md:flex-row gap-3 md:items-center md:justify-between text-sm">
          <div className="flex flex-wrap gap-2 items-center text-slate-300">
            <span className="text-slate-500 uppercase tracking-widest text-[10px] mr-1">Controls</span>
            <kbd className="key">W</kbd><span className="text-slate-400">accelerate</span>
            <kbd className="key">S</kbd><span className="text-slate-400">brake</span>
            <kbd className="key">A</kbd><kbd className="key">D</kbd><span className="text-slate-400">steer</span>
            <kbd className="key">P</kbd><span className="text-slate-400">pause</span>
          </div>
          <button onClick={() => { resetGame(); startGame(); }} className="self-start md:self-auto rounded-lg border border-white/15 px-4 py-2 text-slate-300 hover:border-[#72f5c8]/60 hover:text-[#9fffe0] transition">Restart run</button>
        </footer>
        <p className="mt-3 text-xs text-slate-500">Collect the glowing fruit. Touching the border or your own body ends the run.</p>
        <style>{`.key { display:inline-flex; align-items:center; justify-content:center; min-width:24px; height:24px; padding:0 7px; border:1px solid rgba(255,255,255,.18); border-bottom-width:2px; border-radius:6px; background:rgba(255,255,255,.06); color:#d9fff2; font-size:11px; font-weight:700; }`}</style>
      </section>
    </main>
  );
}

